#!/usr/bin/env ruby
require_relative 'lib/era_zero_validation'
require_relative 'lib/era_zero_compound_conventions'
V=EraZeroValidation
d=V.load_yaml('lexicon/compound_dictionary.yaml');reviews=V.load_yaml('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml')
before=V.fingerprint(d['entries']);prior=d['entries'].map{|e|e['compound_id']};added={}
records=[
 [20,'ongoing_bodily_locomotor_activity','ongoing bodily locomotor activity',nil,
  'The bound actor is the focal material body undergoing coordinated body-local movements constituting a locomotor activity pattern. The body itself generates the pattern through its moving parts; passive carriage or arbitrary physical change alone does not suffice. Whole-body displacement relative to the ground, conscious intention, biological life, a destination, speed or a particular gait is not asserted.',
  ['Passive transport without bodily locomotor activity','An arbitrary internal physical change','Whole-body displacement or conscious intention inferred from the activity']],
 [21,'ongoing_bodily_swimming','ongoing bodily swimming','ongoing_bodily_locomotor_activity',
  'The same actor performs bodily locomotor activity whose coordinated movements generate swimming propulsion against surrounding water. Water and the propulsion-producing interaction are part of this conventional meaning, not inferred from a noun label. Limb, fin, tail or body movements may contribute; assistance or equipment is not excluded. The activity need not produce net ground-relative progress, as when opposing a current. Mere floating, passive drifting, riding in a boat, or being carried through water does not suffice. No destination, crossing completion, speed, voluntary intention or absence of assistance is asserted.',
  ['Passive floating, drifting or transport alone','Machine operation, figurative swimming or unspecified fluid movement','Completed crossing, arrival or unassisted activity inferred from swimming']],
 [22,'ongoing_swimming_across_region','ongoing swimming across a region','ongoing_bodily_swimming',
  'The same actor is swimming along a traversal path through the bound spatial region, progressing from a contextual side toward an opposed side of that region. The swimming supplies this traversal, not an unrelated simultaneous activity. The region is a traversed spatial extent, not a recipient, source of propulsion or already reached destination. The event is ongoing and does not assert that the actor has reached the opposite side or completed the crossing. No particular speed, straightness, intention, unassisted activity or subsequent location is asserted.',
  ['Swimming somewhere within a region without across-traversal','A completed crossing inferred from ongoing activity','The region treated as a recipient or a separately moving actor']]
]
records.each do |code,key,title,dependency,definition,excludes|
 nodes=dependency ? [{'node_id'=>'h','kind'=>'compound_ref','compound_id'=>added.fetch(dependency),'definition_version'=>'1.0.0'}] : [{'node_id'=>'q-body','kind'=>'root','root_id'=>'MAT:000'},{'node_id'=>'s-actor','kind'=>'slot','slot_name'=>'actor','slot_type'=>'entity'},{'node_id'=>'h','kind'=>'root','root_id'=>'MAT:101'}]
 if code==22;nodes.unshift({'node_id'=>'s-region','kind'=>'slot','slot_name'=>'region','slot_type'=>'entity'});end
 edges=dependency ? (code==22 ? [{'type'=>'fills_role','from'=>'s-region','to'=>'h','role'=>'environment'}] : []) : [{'type'=>'qualifies','from'=>'q-body','to'=>'h'},{'type'=>'fills_role','from'=>'s-actor','to'=>'h','role'=>'actor'}]
 meaning={'profile'=>'EZLEX-1','sense_key'=>key,'sound_code'=>code,'added_definition'=>definition,'excludes'=>excludes}
 payload={'architecture_version'=>'1.0','semantic_head'=>'h','nodes'=>nodes,'edges'=>edges,'lexical_constraints'=>['The bound actor anchors the same focal material body and local physical changes throughout the nested activity.','Locomotor pattern and specialization are explicit audible conventions, not consequences of root adjacency.','Runtime, grammatical negation, time and path completion are independent.'],'conventional_meaning'=>meaning}
 digest=V.fingerprint(payload);id="CMP:#{digest[0,24]}";added[key]=id
 entry=payload.merge('compound_id'=>id,'content_digest'=>digest,'definition_version'=>'1.0.0','status'=>'approved','approval_date'=>'2026-11-04','display_title'=>title,'english_glosses'=>[title],'invariant_definition'=>definition,'boundaries'=>{'includes'=>definition,'excludes'=>excludes.join('; ')},'collision_audit'=>'reviews/locomotion_foundations.md and reviews/swimming_foundation.md; physical change alone does not entail the declared locomotor pattern.','confidence'=>'high','approval_record'=>(code==22 ? 'migrations/swimming_across_2026_11_04.yaml' : 'migrations/swimming_2026_11_04.yaml'),'approval_basis'=>'Delegated author review under the user-directed translator completion goal; not independent linguistic validation.','examples'=>{'ordinary'=>dependency ? 'Eli is swimming.' : 'The actor performs bodily locomotor activity.','technical'=>'Preserve the same bound actor in each version-pinned dependency.','future_compound'=>'Add a path only with the same actor and event binding.','counterexample'=>excludes.first},'serialization'=>{'canonical_format'=>'EZC-JSON-1','content_digest'=>digest})
 old=d['entries'].find{|e|e['compound_id']==id};raise 'Existing activity changed' if old&&old!=entry;d['entries']<<entry unless old
 unless reviews['reviews'].any?{|r|r['compound_id']==id}
  candidates=[['explicit_activity_convention','Physical ingredients remain true; the convention supplies pattern and manner.',[9,10,10,9,9,10,8,10],'winner'],['generic_displacement','Displacement loses bodily propulsion and can exclude in-place activity.',[8,9,9,2,3,4,3,4],'rejected'],['runtime_as_manner','Runtime does not encode gait, water or propulsion.',[1,2,2,1,1,1,2,1],'rejected']].map{|name,reason,scores,decision|{'candidate_id'=>name,'direction'=>reason,'scores'=>V::SCORE_KEYS.zip(scores).to_h,'total'=>scores.sum,'decision'=>decision}}
  candidates[0]['graph']=payload.slice('semantic_head','nodes','edges','conventional_meaning')
  reviews['reviews']<<{'compound_id'=>id,'display_title'=>title,'current_choice_reason'=>'reviews/swimming_foundation.md; author judgments, not independent validation.','candidates'=>candidates,'recommendation'=>'approve explicit_activity_convention','confidence'=>'high'}
 end
end
EraZeroCompoundConventions.validate!(d['entries']);d['entries'].sort_by!{|e|e['compound_id']};d['metadata']['entry_count']=d['entries'].length
V.write('lexicon/compound_dictionary.yaml',YAML.dump(d));V.write('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml',YAML.dump(reviews))
cases=V.load_yaml('tests/gate4b_compound_cases.yaml');cases['metadata']['approved_entries']=d['entries'].length;cases['accepted']=d['entries'].map{|e|{'case_id'=>e['display_title'].tr(' ','_'),'compound_id'=>e['compound_id'],'expected'=>'valid_approved_entry'}};V.write('tests/gate4b_compound_cases.yaml',YAML.dump(cases))
version=V.load_yaml('spec/version.yaml');version['compound_dictionary_entries']=d['entries'].length;V.write('spec/version.yaml',YAML.dump(version))
migration='migrations/swimming_2026_11_04.yaml';V.write(migration,YAML.dump({'authority'=>'User-directed translator-completion goal','review'=>'reviews/swimming_foundation.md','before_dictionary_fingerprint'=>before,'previous_compound_ids'=>prior,'added_compounds'=>added,'new_convention_codes'=>[20,21],'existing_meanings_changed'=>false})) unless File.exist?(File.join(V::ROOT,migration))
V.write('pages/swimming.mjs',"export const SWIMMING = #{JSON.generate({pattern:'swimming',predicate:added.fetch('ongoing_bodily_swimming'),key:'ongoing_bodily_swimming',wording:'is swimming',role:'actor',compoundSlots:{actor:['h','s-actor']},semanticNote:records[1][4]})};\n")
puts JSON.pretty_generate(added)

path='migrations/swimming_across_2026_11_04.yaml'
V.write(path,YAML.dump({'authority'=>'User-directed translator-completion goal','review'=>'reviews/swimming_across.md','before_dictionary_fingerprint'=>before,'previous_compound_ids'=>prior,'added_compounds'=>added.select{|k,v|k=='ongoing_swimming_across_region'},'new_convention_codes'=>[22],'existing_meanings_changed'=>false})) unless File.exist?(File.join(V::ROOT,path))
File.open(File.join(V::ROOT,'pages/swimming.mjs'),'a'){|f|f.puts "export const SWIMMING_ACROSS = #{JSON.generate({predicate:added.fetch('ongoing_swimming_across_region'),key:'ongoing_swimming_across_region',wording:'is swimming across',role:'actor',compoundSlots:{actor:['h','h','s-actor'],environment:['s-region']},semanticNote:records[2][4]})};"}
